/** Scheduled execution plumbing with injected synthetic agent, never provider/shell dispatch. */
import assert from 'node:assert/strict';import{mkdirSync,writeFileSync}from'node:fs';import{join}from'node:path';import{monitorEventLoopDelay,performance}from'node:perf_hooks';
import{initDatabase,getDb,closeDatabase}from'../../src/db/connection.js';import{createTask,getTaskById,getTaskRunLogs}from'../../src/db/tasks.js';
import{createWebSession,getWebSession}from'../../src/db/web-sessions.js';import{runScheduledTask,resetSchedulerMetricsForTests,getSchedulerMetrics}from'../../src/task-scheduler.js';
import{assertPathWithinTestFilesystemIsolation}from'../../scripts/test-filesystem-isolation.js';
const workspace=process.env.PICLAW_WORKSPACE!;assertPathWithinTestFilesystemIsolation(workspace,process.env,{allowRoot:false});assert.equal(process.env.PICLAW_DB_IN_MEMORY,'0');const instrument=process.argv[2]==='instrument';
mkdirSync(join(workspace,'.piclaw'),{recursive:true});writeFileSync(join(workspace,'.piclaw/config.json'),JSON.stringify({domains:{access:{mode:'single-user'}}}));const originalFetch=globalThis.fetch;let network=0;const deny=()=>{network++;throw Error('external fetch forbidden')};globalThis.fetch=Object.assign(deny,{preconnect:deny})as typeof fetch;
initDatabase();const db=getDb();for(let n=0;n<20;n++)createTask({id:'synthetic-scheduled-'+n,chat_jid:'web:default',prompt:'synthetic local fixture',notify_on_complete:false,schedule_type:'interval',schedule_value:'60000',next_run:'2026-01-01T00:00:00.000Z',status:'active',created_at:'2026-01-01T00:00:00.000Z'});createWebSession('synthetic-scheduler-cookie','default',3600,'totp');resetSchedulerMetricsForTests();
const query=db.query,prepare=db.prepare,metrics:Record<string,{calls:number;ms:number}>={};const timed=<T>(name:string,fn:()=>T)=>{const at=performance.now();try{return fn()}finally{const m=metrics[name]??={calls:0,ms:0};m.calls++;m.ms+=performance.now()-at}};
const proxies=new WeakMap<object,object>();const wrap=(s:any,sql:string)=>{const previous=proxies.get(s);if(previous)return previous;const p=new Proxy(s,{get(t,k){if(!['get','all','run'].includes(String(k)))return Reflect.get(t,k,t);return(...a:unknown[])=>timed(k==='run'&&sql.includes('INSERT INTO task_run_logs')?'SQL.run.task-log':'SQL.'+String(k),()=>Reflect.apply(t[k],t,a))}});proxies.set(s,p);return p};if(instrument){db.query=((...a:Parameters<typeof query>)=>wrap(timed('SQL.query',()=>Reflect.apply(query,db,a)),a[0]))as typeof query;db.prepare=((...a:Parameters<typeof prepare>)=>wrap(timed('SQL.prepare',()=>Reflect.apply(prepare,db,a)),a[0]))as typeof prepare;}
let agents=0,sends=0,nudges=0,saves=0,restores=0,active=0,maxActive=0;const batches:number[]=[],probes:number[]=[],timerLateness:number[]=[];const loop=monitorEventLoopDelay({resolution:1});loop.enable();let finished=false;
const polling=(async()=>{while(!finished){const at=performance.now();assert.equal(getWebSession('synthetic-scheduler-cookie')?.user_id,'default');probes.push(performance.now()-at);const wake=performance.now()+5;await Bun.sleep(5);timerLateness.push(Math.max(0,performance.now()-wake))}})();
const deps={queue:{enqueueTask:()=>{throw Error('no live queue')}},agentPool:{saveSessionPosition:async()=>{saves++;return'synthetic-leaf'},getCurrentModelLabel:async()=>null,restoreSessionPosition:async()=>{restores++},runAgent:async()=>{agents++;active++;maxActive=Math.max(maxActive,active);await Bun.sleep(5);active--;return{status:'success',result:'Synthetic scheduled output'}}},sendMessage:async()=>{sends++},sendNudge:async()=>{nudges++}}as any;
const cpu=process.cpuUsage(),start=performance.now();try{
 for(let batch=0;batch<5;batch++){const at=performance.now();await Promise.all(Array.from({length:4},(_,n)=>runScheduledTask(getTaskById('synthetic-scheduled-'+(batch*4+n))!,deps,{advanceTask:false}).then(r=>assert.equal(r.status,'success'))));batches.push(performance.now()-at);await Bun.sleep(5);}
 finished=true;await polling;await Bun.sleep(10);loop.disable();for(let n=0;n<20;n++){assert.equal(getTaskRunLogs('synthetic-scheduled-'+n).length,1);assert.equal(getTaskById('synthetic-scheduled-'+n)!.next_run,'2026-01-01T00:00:00.000Z');}assert.deepEqual({agents,sends,nudges,saves,restores},{agents:20,sends:20,nudges:0,saves:20,restores:20});assert.equal(network,0);assert.deepEqual(db.query('PRAGMA quick_check').get(),{quick_check:'ok'});console.log(JSON.stringify({runtime:Bun.version,instrument,tasks:20,concurrency:4,maxActive,wallMs:performance.now()-start,cpu:process.cpuUsage(cpu),batches,parentAuthProbes:probes,parentTimerLatenessMs:timerLateness,eventLoop:{samples:loop.count,maxMs:loop.max/1e6,meanMs:loop.mean/1e6},metrics:instrument?metrics:null,scheduler:getSchedulerMetrics(),settings:{journal:db.query('PRAGMA journal_mode').get(),synchronous:db.query('PRAGMA synchronous').get()},network,scope:'Actual legacy scheduled-run plumbing/task logs with injected synthetic 5ms agent and outbound sinks. No real Agent/model/provider, live scheduling, shell, notifications or durable claim-loop execution. advanceTaskfalse preserves recurrence; correctness asserts20logs and20restore-callback/sink invocations, not real restored SDK leaves or external deliveries. In-report methodCPU excludes startup/seed; external wholechildCPUprofile includes them. Queryduration and parenttimerlateness separate; no universal network sandbox beyond interceptedfetch.'}));
}finally{finished=true;await polling;loop.disable();db.query=query;db.prepare=prepare;globalThis.fetch=originalFetch;closeDatabase()}
